mapper.select:
select
    industry_name,
    count(*) as customer_count,
    sum(risk_score >= 65) as high_risk_count,
    ifnull(sum(case when risk_score >= 65 then ead_amount_total else 0 end), 0) as high_risk_ead_amount
from (

) risk_base
group by industry_name
order by high_risk_count desc, high_risk_ead_amount desc, customer_count desc
limit #{limit}
